40	const RULE = 'D59';
41	const EXPECTED_CHECKS = 5;
42	const ENTRY = 'corpus/knowledge/mcp-orchestration-contract.md';
43	
44	const [laneArg, rev, ...rest] = process.argv.slice(2);
45	if (!laneArg || !rev || rest.length) {
46	  process.stderr.write('DOCTRINE59: USAGE node doctrine59-probe.mjs <lane> <rev>\n');
47	  process.exit(64);
48	}
49	const lane = resolve(laneArg);
50	if (!existsSync(join(lane, '.git'))) {
51	  process.stderr.write(`DOCTRINE59: USAGE ${JSON.stringify(lane)} is not a git repo\n`);
52	  process.exit(64);
53	}
54	if (!/^[0-9a-f]{7,64}$/.test(rev)) {
55	  process.stderr.write('DOCTRINE59: USAGE <rev> must be a lowercase hex object name\n');
56	  process.exit(64);
57	}
58	const sha = (b) => createHash('sha256').update(b).digest('hex');
59	const checks = [];
60	const hold = (id, ok, detail) => checks.push({ id, ok, detail });
61	const T = mkdtempSync(join(tmpdir(), 'd59-probe.'));
62	
63	function finish(code, line) {
64	  rmSync(T, { recursive: true, force: true });
65	  process.stdout.write(line + '\n');
66	  for (const c of checks) process.stdout.write(` | ${c.id} ${c.ok ? 'PASS' : 'MISS'} ${c.detail}`);
67	  if (checks.length) process.stdout.write('\n');
68	  process.exit(code);
69	}
70	
71	try {
72	  const tar = spawnSync('bash', ['-lc',
73	    `git -C ${JSON.stringify(lane)} archive ${JSON.stringify(rev)} | tar -x -C ${JSON.stringify(T)}`],
74	    { encoding: 'utf8', timeout: 180000 });
