82	
83	  {
84	    const entry = text(ENTRY);
85	    if (!entry) hold('E1', false, 'entry-absent');
86	    else {
87	      const lines = entry.split('\n');
88	      const head = lines.slice(0, 5).join('\n');
89	      const ok = /S125/.test(lines[0] || '') && /S127/.test(lines[0] || '') && /S136/.test(lines[0] || '')
90	        && /modelcontextprotocol\.io/.test(lines[0] || '')
