104	      const blob = readT(m[1]);
105	      if (!blob || sha(blob) !== m[2]) hashMiss += 1;
106	    }
107	    const distinct = new Set(paths).size === paths.length && paths.length >= 8;
108	    const ok = clauses.length >= 8 && distinct && hashMiss === 0;
109	    hold('E2', ok, `clauses=${clauses.length} distinct=${new Set(paths).size} hash-miss=${hashMiss}`);
110	  }
111	  {
112	    const sources = text('corpus/SOURCES.md') || '';
113	    const pins = text('.ufo/pins/source-captures.json');
114	    let pinDoc = null;
115	    try { pinDoc = pins ? JSON.parse(pins) : null; } catch { pinDoc = null; }
116	    const want = ['S125', 'S127', 'S136'];
117	    let rowOk = true;
118	    const why = [];
119	    for (const id of want) {
