121	      if (!row) { rowOk = false; why.push(`${id}:missing`); continue; }
122	      const cells = row.split('|').slice(1, -1).map((c) => c.trim());
123	      if (cells.length !== 11) { rowOk = false; why.push(`${id}:cols=${cells.length}`); }
124	      if (cells[7] !== 'mined') { rowOk = false; why.push(`${id}:status`); }
125	      if (!String(cells[10] || '').includes(ENTRY)) { rowOk = false; why.push(`${id}:used-by`); }
126	      if (row.includes('\\|')) { rowOk = false; why.push(`${id}:escaped-pipe`); }
127	    }
128	    let pinOk = true;
129	    const captures = pinDoc && Array.isArray(pinDoc.captures) ? pinDoc.captures : [];
130	    for (const id of want) {
131	      const pin = captures.find((c) => c.sourceId === id);
132	      if (!pin) { pinOk = false; why.push(`${id}:unpin`); continue; }
133	      const blob = readT(pin.path);
134	      if (!blob || sha(blob) !== pin.sha256) { pinOk = false; why.push(`${id}:pin-miss`); }
135	    }
136	    hold('E3', rowOk && pinOk, why.length ? why.join(',') : 'rows+pins');
137	  }
138	  {
139	    const lesson = text('corpus/lessons/round-59.md') || '';
140	    const admit = lesson.includes('ADMIT mcp-orchestration-contract.md');
141	    const r1 = lesson.includes('REJECT durable-execution-and-fanout-primitives-2026-10-24.md');
142	    const r2 = lesson.includes('REJECT durable-execution-failure-detection.md');
143	    const flips = (lesson.match(/flip:/g) || []).length;
144	    const ok = admit && r1 && r2 && flips >= 2;
145	    hold('E4', ok, `admit=${admit} fanout=${r1} detect=${r2} flips=${flips}`);
146	  }
