148	    const col = text('.ufo/waves/round-59/assimilation/collisions');
149	    const reg = text('.ufo/waves/round-59/assimilation/reg-ids') || '';
150	    const staged = text('.ufo/waves/round-59/assimilation/staged-ids') || '';

