161	const held = checks.filter((c) => c.ok).length;
162	const mismatch = checks.length !== EXPECTED_CHECKS;
163	const head = `DOCTRINE59: ${mismatch ? 'DOCTRINE59_UNMET' : (held === EXPECTED_CHECKS ? 'DOCTRINE59_HELD' : 'DOCTRINE59_UNMET')} held=${held}/${checks.length} checks=${EXPECTED_CHECKS} rev=${rev} rule=${RULE}${mismatch ? ' checks-mismatch' : ''}`;
164	finish(held === EXPECTED_CHECKS && !mismatch ? 0 : 1, head);
